import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';


export type ChurchLifeTransitionProps = Record<string, any>;

const ChurchLifeTransition: React.FC<ChurchLifeTransitionProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 3,
  primaryGradientStart = "#0a192f",
  primaryGradientEnd = "#4a148c",
  sweepColorWhite = "#ffffff",
  sweepColorGold = "#ffb300",
  accentGreen = "#00e676",
  accentBlue = "#2979ff",
  accentRed = "#ff1744",
  accentPurple = "#d500f9",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Global sweep progress
  const txProgress = interpolate(frame, [0, totalFrames], [0, 1], {
    easing: Easing.bezier(0.7, 0, 0.3, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // baseX tracks the RIGHT edge of the Main Gradient block.
  // It starts far left (-width * 0.5) and ends far right (width * 3.5).
  // At txProgress = 0.5, baseX is exactly width * 1.5, perfectly covering the 16:9 canvas.
  const baseX = interpolate(txProgress, [0, 1], [-width * 0.5, width * 3.5]);

  // Expansion creates a subtle breathing/layered effect in the middle of the transition.
  const exp = interpolate(txProgress, [0, 0.5, 1], [0, width * 0.1, 0]);

  const sharedStyle: React.CSSProperties = {
    position: "absolute",
    top: "-50%",
    height: "200%",
    left: 0,
    transition: "none",
  };

  // Small geometric accents floating with parallax
  const accents = [
    { color: accentGreen, size: width * 0.015, relX: width * 0.2, y: 0.2, p: 0.05, layer: "fg" },
    { color: accentBlue, size: width * 0.02, relX: width * 0.1, y: 0.8, p: -0.02, layer: "fg" },
    { color: accentRed, size: width * 0.01, relX: width * 0.3, y: 0.5, p: 0.03, layer: "fg" },
    { color: accentPurple, size: width * 0.025, relX: width * 0.15, y: 0.3, p: -0.04, layer: "fg" },
    { color: accentGreen, size: width * 0.01, relX: -width * 2.6, y: 0.65, p: 0.06, layer: "bg" },
    { color: accentBlue, size: width * 0.018, relX: -width * 2.8, y: 0.35, p: -0.03, layer: "bg" },
    { color: accentRed, size: width * 0.008, relX: -width * 2.5, y: 0.15, p: 0.02, layer: "bg" },
    { color: accentPurple, size: width * 0.015, relX: -width * 2.7, y: 0.85, p: -0.05, layer: "bg" },
  ];

  const renderAccents = (layerType: string) => {
    return accents
      .filter((a) => a.layer === layerType)
      .map((a, i) => {
        const px = baseX * (1 + a.p) + a.relX;
        const py = a.y * height + Math.sin((frame + i * 10) / 15) * (height * 0.02);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: a.size,
              height: a.size,
              borderRadius: "50%",
              backgroundColor: a.color,
              transform: `translate(${px}px, ${py}px)`,
              boxShadow: `0 0 ${width * 0.01}px ${a.color}80`,
              opacity: 0.9,
              transition: "none",
            }}
          />
        );
      });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden", transition: "none" }}>
      {/* Background Accents */}
      {renderAccents("bg")}

      {/* Trailing Gold Edge (Drawn first, lowest layer) */}
      <div
        style={{
          ...sharedStyle,
          width: width * 0.2,
          backgroundColor: sweepColorGold,
          transform: `translateX(${baseX - width * 2.65 - exp * 1.5}px) skewX(-25deg)`,
          boxShadow: `0 0 ${width * 0.02}px ${sweepColorGold}80`,
        }}
      />

      {/* Trailing White Edge */}
      <div
        style={{
          ...sharedStyle,
          width: width * 0.3,
          backgroundColor: sweepColorWhite,
          transform: `translateX(${baseX - width * 2.6 - exp}px) skewX(-25deg)`,
          boxShadow: `0 0 ${width * 0.02}px ${sweepColorWhite}`,
        }}
      />

      {/* Main Gradient Cover */}
      <div
        style={{
          ...sharedStyle,
          width: width * 2.5,
          background: `linear-gradient(90deg, ${primaryGradientStart}, ${primaryGradientEnd})`,
          transform: `translateX(${baseX - width * 2.5}px) skewX(-25deg)`,
          boxShadow: `0 0 ${width * 0.05}px rgba(0,0,0,0.6)`,
          overflow: "hidden",
        }}
      >
        {/* Soft light sweep internal to the gradient */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            height: "100%",
            width: "40%",
            background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.15), transparent)",
            transform: `translateX(${interpolate(txProgress, [0, 1], [-width, width * 2.5])}px)`,
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            height: "100%",
            width: "20%",
            background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent)",
            transform: `translateX(${interpolate(txProgress, [0, 1], [width * 2.5, -width])}px)`,
            transition: "none",
          }}
        />
      </div>

      {/* Leading White Edge (Overlaps the right side of Main Gradient) */}
      <div
        style={{
          ...sharedStyle,
          width: width * 0.3,
          backgroundColor: sweepColorWhite,
          transform: `translateX(${baseX - width * 0.2 + exp}px) skewX(-25deg)`,
          boxShadow: `0 0 ${width * 0.02}px ${sweepColorWhite}`,
        }}
      />

      {/* Leading Gold Edge */}
      <div
        style={{
          ...sharedStyle,
          width: width * 0.2,
          backgroundColor: sweepColorGold,
          transform: `translateX(${baseX - width * 0.1 + exp * 1.5}px) skewX(-25deg)`,
          boxShadow: `0 0 ${width * 0.015}px ${sweepColorGold}80`,
        }}
      />

      {/* Foreground Accents */}
      {renderAccents("fg")}
    </AbsoluteFill>
  );
};

export default ChurchLifeTransition;